61	+impl<K: Eq + Hash, V: Clone> BatchAnswers<K, V> {
62	+    /// The caller's part in the question `key`.
63	+    pub(crate) fn take(&self, key: K) -> Taken<V> {
64	+        let slot = self
65	+            .slots
66	+            .lock()
67	+            .unwrap_or_else(PoisonError::into_inner)
68	+            .entry(key)
69	+            .or_insert_with(|| Arc::new(Slot { answer: OnceLock::new(), asking: Arc::new(AsyncMutex::new(())) }))
70	+            .clone();
71	+        if slot.answer.get().is_some() {
72	+            return Taken::Kept;
73	+        }
74	+        match slot.asking.clone().try_lock_owned() {
75	+            // Answered between the two looks.
76	+            Ok(_) if slot.answer.get().is_some() => Taken::Kept,
77	+            Ok(asking) => Taken::Mine(Mine { slot, _asking: asking }),
78	+            Err(_) => Taken::Theirs(Theirs(slot.asking.clone())),
79	+        }
80	+    }
81	+
82	+    /// The answer to `key`, when it has one.
83	+    pub(crate) fn peek(&self, key: &K) -> Option<V> {
84	+        self.slots.lock().unwrap_or_else(PoisonError::into_inner).get(key)?.answer.get().cloned()
85	+    }
86	+}
