557	+/// `old` rooted at `files` instead of the files they were opened over: each lane's snapshot is brought to them with
558	+/// `updateSnapshot` (`reconfigurePrograms`), which reads every file as the snapshot holds it and parses only the roots
559	+/// added; the checker works the program's files, globals and ambient declarations out again from the new roots, so a
560	+/// file no root reaches any more declares nothing. The snapshots they replace are released, and the lanes' are the new
561	+/// ones' own to release ([`Lanes::Each`]). Any failure is the caller's to answer by starting the checker again: no
562	+/// answer is given from a partly rooted set.
563	+async fn reroot(old: Vec<Arc<Rpc>>, files: &[String]) -> Result<Vec<Arc<Rpc>>, CallError> {
564	+    let files: Arc<[String]> = files.into();
565	+    let mut tasks = JoinSet::new();
566	+    for (lane, rpc) in old.iter().enumerate() {
567	+        let (rpc, files) = (rpc.clone(), files.clone());
568	+        tasks.spawn(async move { (lane, rpc.updated(&[], &[], Some(&files)).await) });
569	+    }
570	+    let mut rooted: Vec<Option<Rpc>> = old.iter().map(|_| None).collect();
571	+    while let Some(joined) = tasks.join_next().await {
572	+        let (lane, updated) = joined.map_err(|error| CallError::Fatal(format!("a root update failed: {error}")))?;
573	+        if let Some(slot) = rooted.get_mut(lane) {
574	+            *slot = Some(updated?);
575	+        }
576	+    }
577	+    let rooted: Option<Vec<Arc<Rpc>>> = rooted.into_iter().map(|rpc| rpc.map(Arc::new)).collect();
578	+    let rooted = rooted.ok_or_else(|| CallError::Fatal("a lane was not rooted".to_string()))?;
579	+    if let Some(first) = old.first() {
580	+        first.release().await;
581	+    }
582	+    Ok(rooted)
583	+}
