/// that checker asked of the file system (each file it read or looked for, each directory it listed, the tsconfig and
/// what it extends) is asked again first, and any different answer, a new file where it found none included, discards
/// the kept answer whole; so does another build of Caliper or of the pinned checker, and another request. A request
/// that records its calls is answered as [`resolve`] answers it, and nothing is kept for it. The answer is the one
/// [`resolve`] gives, and it is written before the call returns, whatever the request's [`Teardown`].
pub fn resolve_cached(request: SemanticRequest, cache_dir: &Utf8Path) -> SemanticOutcome {
    resolve_cached_early(request, cache_dir, None)
}

/// [`resolve_cached`] over the checker's session when `early` ([`start_early`]) was opened for this request's project,
/// tsconfig and timeout, its programs rooted at the request's files, or brought to them when they were not
/// (`updateSnapshot`); it is dropped otherwise, and when the kept answer is used.
pub fn resolve_cached_early(
    request: SemanticRequest,
    cache_dir: &Utf8Path,
    early: Option<EarlyStart>,
) -> SemanticOutcome {
    if request.record_to.is_some() {
        discard(early);
        return resolve(request);
    }
    let file = cache_dir.join(kept::FILE);
    let key = kept::request_key(&request);
    let started = std::time::Instant::now();
    if let Some(outcome) = kept::load(&file, key) {
        discard(early);
        tracing::debug!(ms = started.elapsed().as_millis() as u64, "the checker's kept answer still holds");
        return outcome;
    }
    // The answer saved below carries what the run read: a program that did not note its reads cannot be used.
    let noted = early.as_ref().is_some_and(|early| early.reads.is_some());
    let early = fitting(early, &request, noted);
    let reads = early.as_ref().and_then(|early| early.reads.clone()).unwrap_or_default();
    let outcome = resolve_with(request, Some(reads.clone()), early);
    kept::save(&file, key, &reads, &outcome);
    outcome
}

/// [`resolve`] over the session an early start opened ([`start_early`]) when it was opened for this request's project,
/// tsconfig and timeout, and as [`resolve`] does otherwise.
pub fn resolve_early(request: SemanticRequest, early: Option<EarlyStart>) -> SemanticOutcome {
    // Early programs are opened without a recording.
    let early = fitting(early, &request, request.record_to.is_none());
    resolve_with(request, None, early)
}

/// `early` when `usable` and it [`fits`](EarlyStart::fits) `request`'s setup; otherwise it is stopped and there is none.
fn fitting(early: Option<EarlyStart>, request: &SemanticRequest, usable: bool) -> Option<EarlyStart> {
    match early {
        Some(early) if usable && early.fits(request) => Some(early),
        other => {
            discard(other);
            None
        }
    }
}

/// What an early start opened: the checker and the programs rooted at `roots`, or the outcome its failure gives.
struct Opened {
    runtime: tokio::runtime::Runtime,
    checker: Backend,
    programs: Result<Vec<Arc<Rpc>>, SemanticOutcome>,
}

/// The checker started, and its program opened, on a thread of its own before the structural pass is done: the
/// program needs only the root files (the files of the exported components), the project root and the tsconfig. The run
            .map(|part| scope.spawn(move || part.iter().all(|(question, answer)| question.answer(fs) == *answer)))
            .collect();
        checks.into_iter().all(|check| check.join().unwrap_or(false))
    })
}

/// Keeps `outcome` at `file` for the request `key` names, with the questions `reads` noted. Nothing is kept for an
/// outcome with a diagnostic, a degraded one (the checker was unavailable, or failed on a component: `to_bytes` refuses
/// it, [`SemanticOutcome::is_degraded`]) or a run that read more than one state of the disk; a failure to write is
/// logged and otherwise ignored (the next run asks the checker again).
pub(crate) fn save(file: &Utf8Path, key: u128, reads: &Reads, outcome: &SemanticOutcome) {
    if !outcome.diagnostics.is_empty() {
        return;
    }
    let Some(reads) = reads.settled() else {
        tracing::debug!("the checker read a file that changed during the run; its answer is not kept");
        return;
    };
    let written = (|| -> Result<(), String> {
        let mut bytes = rmp_serde::to_vec(&Header::of(key)).map_err(|error| error.to_string())?;
        bytes.extend(rmp_serde::to_vec(&reads).map_err(|error| error.to_string())?);
        bytes.extend(outcome.to_bytes()?);
        let dir = file.parent().ok_or_else(|| "no directory".to_string())?;
        std::fs::create_dir_all(dir).map_err(|error| error.to_string())?;
        // A name of its own per process, so two runs sharing the directory do not write one temporary file.
        let temporary = dir.join(format!("{FILE}.{}.tmp", std::process::id()));
        let result = std::fs::write(&temporary, &bytes).and_then(|()| std::fs::rename(&temporary, file));
        if result.is_err() {
            std::fs::remove_file(&temporary).ok();
        }
        result.map_err(|error| error.to_string())
    })();
    if let Err(error) = written {
        tracing::debug!("could not keep the checker's answer at {file}: {error}");
    }
}

